//! Provenance classes (FINAL 2.0 §11): where a piece of index data came from.

use serde::{Deserialize, Serialize};

/// The origin of one recognition result or index entry. Every machine result carries one; the
/// search never shows a relevance score as proof of fact.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum Provenance {
    /// Typed or confirmed by a person.
    Human,
    /// Generated by a model.
    AiGenerated,
    /// A model transformed existing data.
    AiTransformed,
    /// Model output a person then edited.
    AiDerivedHumanEdited,
    /// Taken from a source file (an imported subtitle, a metadata field).
    SourceDerived,
    /// Extracted by a deterministic tool (a scene detector, a hash).
    MachineExtracted,
    /// More than one of the above.
    Mixed,
    /// Origin not known; never treated as verified.
    Unknown,
}

impl Provenance {
    /// True when a model or tool, not a person or a source file, produced the data.
    pub fn is_machine(self) -> bool {
        matches!(self, Self::AiGenerated | Self::AiTransformed | Self::MachineExtracted)
    }

    /// True only for data a person wrote or confirmed.
    pub fn is_human_verified(self) -> bool {
        matches!(self, Self::Human | Self::AiDerivedHumanEdited)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn serialises_as_upper_snake() {
        assert_eq!(serde_json::to_string(&Provenance::AiDerivedHumanEdited).unwrap(), "\"AI_DERIVED_HUMAN_EDITED\"");
        let back: Provenance = serde_json::from_str("\"MACHINE_EXTRACTED\"").unwrap();
        assert_eq!(back, Provenance::MachineExtracted);
    }

    #[test]
    fn unknown_text_is_an_error_not_a_default() {
        assert!(serde_json::from_str::<Provenance>("\"VERIFIED\"").is_err());
    }

    #[test]
    fn machine_and_human_classes_do_not_overlap() {
        for p in [
            Provenance::Human,
            Provenance::AiGenerated,
            Provenance::AiTransformed,
            Provenance::AiDerivedHumanEdited,
            Provenance::SourceDerived,
            Provenance::MachineExtracted,
            Provenance::Mixed,
            Provenance::Unknown,
        ] {
            assert!(!(p.is_machine() && p.is_human_verified()), "{p:?}");
        }
        assert!(!Provenance::Unknown.is_human_verified());
        assert!(!Provenance::Mixed.is_human_verified());
    }
}
